def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); pts=[]
            while stack:
                a,b=stack.pop(); pts.append((a,b))
                for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==color:
                        seen.add((x,y)); stack.append((x,y))
            comps.append(pts)
    centers=[(sum(r for r,c in p)/len(p),sum(c for r,c in p)/len(p)) for p in comps]
    out=[[0]*w for _ in range(h)]
    if not comps: return out
    # The central block is the one between the other blocks.
    best=min(range(len(comps)),key=lambda i:sum(((centers[i][0]-a)**2+(centers[i][1]-b)**2)**0.5 for a,b in centers))
    for r,c in comps[best]: out[r][c]=grid[r][c]
    return out

